// Home bot: Seerr requests, downloads, server status and power, by polling the bot (n8n stays private).
// Only obeys TELEGRAM_CHAT_ID. Service keys come from homepage.secret via $env.
const TOKEN = $env.HOMELAB_TELEGRAM_BOT_TOKEN, CHAT = String($env.HOMELAB_TELEGRAM_CHAT_ID || '');
const PVE = 'https://192.168.3.200:8006/api2/json/nodes/pve';
const PVE_AUTH = `PVEAPIToken=${$env.HOMELAB_PVE_POWER_TOKEN_ID}=${$env.HOMELAB_PVE_POWER_TOKEN_SECRET}`;
const CONFIRM_SECONDS = 120;
if (!TOKEN || !CHAT) throw new Error('Set HOMELAB_TELEGRAM_BOT_TOKEN and HOMELAB_TELEGRAM_CHAT_ID in docker/n8n/.env');

const helpers = this.helpers;
const s = $getWorkflowStaticData('global');
const tg = (method, body) => helpers.httpRequest({ method: 'POST', url: `https://api.telegram.org/bot${TOKEN}/${method}`, body, json: true, timeout: 15000 });
const say = (text) => tg('sendMessage', { chat_id: CHAT, text });
const pve = (method, path, form) => helpers.httpRequest({
  method, url: `${PVE}${path}`, headers: { Authorization: PVE_AUTH, ...(form ? { 'Content-Type': 'application/x-www-form-urlencoded' } : {}) },
  body: form, json: true, skipSslCertificateValidation: true, timeout: 15000 });


const LAN = 'http://192.168.3.201';
const seerr = (method, path, opts = {}) => helpers.httpRequest({ method, url: `${LAN}:5055/api/v1${path}`,
  headers: { 'X-Api-Key': $env.HOMEPAGE_VAR_SEERR_KEY || '' }, json: true, timeout: 20000, ...opts });
const STATUS = { 2: '🕓 Requested', 3: '⏳ Downloading/processing', 4: '🟡 Partly in library', 5: '✅ In library' };
const REQ_STATUS = { 1: '🕓 Pending approval', 2: '👍 Approved', 3: '❌ Declined', 4: '⚠️ Failed', 5: '✅ Completed' };
const year = (r) => (r.releaseDate || r.firstAirDate || '').slice(0, 4);
const titleOf = (r) => r.title || r.name || 'Unknown';
const fmtEta = (sec) => sec >= 8640000 || sec < 0 ? '∞' : sec >= 3600 ? `${Math.floor(sec / 3600)} h ${Math.round(sec % 3600 / 60)} min` : `${Math.max(1, Math.round(sec / 60))} min`;

async function search(type, query) {
  if (!query) return say(`Usage: /${type === 'movie' ? 'movie' : 'show'} <title>, e.g. /${type === 'movie' ? 'movie dune' : 'show the bear'}`);
  const r = await seerr('GET', '/search', { qs: { query, page: 1, language: 'en' } });
  const hits = (r.results || []).filter(x => x.mediaType === type).slice(0, 5);
  if (!hits.length) return say(`No ${type === 'movie' ? 'movies' : 'shows'} found for “${query}”.`);
  s.search = { type, hits: hits.map(h => ({ id: h.id, title: titleOf(h), year: year(h), status: h.mediaInfo?.status || 1 })), expires: Date.now() + 10 * 60000 };
  const lines = s.search.hits.map((h, i) => `${i + 1}. ${h.title}${h.year ? ` (${h.year})` : ''}${STATUS[h.status] ? `  ${STATUS[h.status]}` : ''}`);
  return say(`${type === 'movie' ? '🎬' : '📺'} Results for “${query}”:\n${lines.join('\n')}\n\nReply /pick <number> to request.`);
}

async function pick(n) {
  const sr = s.search;
  if (!sr || Date.now() > sr.expires) return say('No recent search. Use /movie <title> or /show <title> first.');
  const h = sr.hits[Number(n) - 1];
  if (!h) return say(`Pick a number from 1 to ${sr.hits.length}.`);
  if (ARR[sr.type]) return pickArr(sr.type, h);
  if (h.status >= 2) return say(`${h.title} is already ${STATUS[h.status].replace(/^\S+ /, '').toLowerCase()}. Nothing to do.`);
  const body = sr.type === 'movie' ? { mediaType: 'movie', mediaId: h.id } : { mediaType: 'tv', mediaId: h.id, seasons: 'all' };
  await seerr('POST', '/request', { body });
  h.status = 2;
  return say(`✅ Requested ${h.title}${h.year ? ` (${h.year})` : ''}. ${sr.type === 'movie' ? 'Radarr' : 'Sonarr'} will start looking for it now. You'll get a message when it lands in Jellyfin.`);
}

async function recentRequests() {
  const r = await seerr('GET', '/request', { qs: { take: 5, skip: 0, sort: 'added', filter: 'all' } });
  const items = r.results || [];
  if (!items.length) return say('No requests yet.');
  const lines = await Promise.all(items.map(async (q) => {
    let name = `${q.type === 'movie' ? 'Movie' : 'Show'} #${q.media?.tmdbId}`;
    try { const d = await seerr('GET', `/${q.type === 'movie' ? 'movie' : 'tv'}/${q.media?.tmdbId}`); name = titleOf(d); } catch (e) {}
    const st = q.media?.status === 5 ? '✅ In library' : (REQ_STATUS[q.status] || '');
    return `• ${name}  ${st}`;
  }));
  return say(`🙋 Recent requests:\n${lines.join('\n')}`);
}

async function downloads() {
  const login = await helpers.httpRequest({ method: 'POST', url: `${LAN}:8080/api/v2/auth/login`,
    headers: { 'Content-Type': 'application/x-www-form-urlencoded', Referer: `${LAN}:8080` },
    body: `username=${encodeURIComponent($env.HOMEPAGE_VAR_QBIT_USER || '')}&password=${encodeURIComponent($env.HOMEPAGE_VAR_QBIT_PASS || '')}`,
    returnFullResponse: true, timeout: 15000 });
  const cookie = [].concat(login.headers?.['set-cookie'] || []).map(c => c.split(';')[0]).join('; ');
  if (!cookie) return say('Could not log in to qBittorrent. Check QBIT_USER / QBIT_PASS in homepage.secret.');
  const list = await helpers.httpRequest({ url: `${LAN}:8080/api/v2/torrents/info`, qs: { filter: 'downloading', sort: 'progress', reverse: true },
    headers: { Cookie: cookie, Referer: `${LAN}:8080` }, json: true, timeout: 15000 });
  if (!list.length) return say('📥 Nothing downloading right now.');
  const lines = list.slice(0, 8).map(t => `• ${t.name.slice(0, 60)}\n   ${Math.round(t.progress * 100)}% · ${(t.dlspeed / 1e6).toFixed(1)} MB/s · ${fmtEta(t.eta)} left`);
  return say(`📥 Downloading (${list.length}):\n${lines.join('\n')}`);
}

// ---- Lidarr (music) and Bookshelf (ebooks / audiobooks) ----
const ARR = {
  music:     { url: `${LAN}:8686/api/v1`, key: $env.HOMEPAGE_VAR_LIDARR_KEY, app: 'Lidarr', icon: '🎵', lib: 'Jellyfin and Navidrome' },
  ebook:     { url: `${LAN}:8788/api/v1`, key: $env.HOMEPAGE_VAR_BOOKSHELF_EBOOK_KEY, app: 'Bookshelf (ebooks)', icon: '📚', lib: 'Calibre-Web' },
  audiobook: { url: `${LAN}:8787/api/v1`, key: $env.HOMEPAGE_VAR_BOOKSHELF_AUDIO_KEY, app: 'Bookshelf (audio)', icon: '🎧', lib: 'Audiobookshelf' },
};
const arr = (kind, method, path, opts = {}) => helpers.httpRequest({ method, url: `${ARR[kind].url}${path}`,
  headers: { 'X-Api-Key': ARR[kind].key || '' }, json: true, timeout: 90000, ...opts });

async function arrDefaults(kind) {
  const roots = await arr(kind, 'GET', '/rootfolder');
  const root = roots[0];
  if (!root) throw new Error(`no root folder set in ${ARR[kind].app}`);
  let q = root.defaultQualityProfileId, m = root.defaultMetadataProfileId;
  if (!q) q = (await arr(kind, 'GET', '/qualityprofile'))[0]?.id;
  if (!m) m = (await arr(kind, 'GET', '/metadataprofile'))[0]?.id;
  return { rootFolderPath: root.path, qualityProfileId: q, metadataProfileId: m };
}

async function searchArr(kind, query) {
  if (!query) return say(`Usage: /${kind} <name>, e.g. /${kind} ${kind === 'music' ? 'burna boy' : 'atomic habits'}`);
  if (kind === 'music') {
    const r = await arr('music', 'GET', '/artist/lookup', { qs: { term: query } });
    const hits = r.slice(0, 5);
    if (!hits.length) return say(`No artists found for “${query}”.`);
    s.search = { type: 'music', hits, expires: Date.now() + 10 * 60000 };
    const lines = hits.map((a, i) => `${i + 1}. ${a.artistName}${a.genres?.length ? ` (${a.genres.slice(0, 2).join(', ')})` : ''}${a.id ? '  ✅ In library' : ''}`);
    return say(`🎵 Artists for “${query}”:\n${lines.join('\n')}\n\nReply /pick <number> to add the artist (latest album is downloaded).`);
  }
  const r = await arr(kind, 'GET', '/book/lookup', { qs: { term: query } });
  const hits = r.slice(0, 5);
  if (!hits.length) return say(`No books found for “${query}”.`);
  s.search = { type: kind, hits, expires: Date.now() + 10 * 60000 };
  const lines = hits.map((b, i) => {
    const y = (b.releaseDate || '').slice(0, 4);
    return `${i + 1}. ${b.title}${y ? ` (${y})` : ''}${b.author?.authorName ? ` by ${b.author.authorName}` : ''}${b.id ? '  ✅ In library' : ''}`;
  });
  return say(`${ARR[kind].icon} ${kind === 'ebook' ? 'Ebooks' : 'Audiobooks'} for “${query}”:\n${lines.join('\n')}\n\nReply /pick <number> to request.`);
}

async function pickArr(kind, hit) {
  const a = ARR[kind];
  if (hit.id) return say(`That's already in ${a.app}. Nothing to do.`);
  const d = await arrDefaults(kind);
  if (kind === 'music') {
    await arr('music', 'POST', '/artist', { body: { ...hit, ...d, monitored: true,
      addOptions: { monitor: 'latest', searchForMissingAlbums: true } } });
    hit.id = -1;
    return say(`✅ Added ${hit.artistName} to Lidarr. Their latest album is being searched for now and will appear in ${a.lib}.\nOlder albums can be added from Lidarr anytime.`);
  }
  const author = { ...(hit.author || {}), ...d, monitored: false,
    addOptions: { monitor: 'none', searchForMissingBooks: false } };
  await arr(kind, 'POST', '/book', { body: { ...hit, author, monitored: true, addOptions: { searchForNewBook: true } } });
  hit.id = -1;
  return say(`✅ Requested ${hit.title}${hit.author?.authorName ? ` by ${hit.author.authorName}` : ''}. ${a.app} is searching for it now; it will appear in ${a.lib}.`);
}

const res = await tg('getUpdates', { offset: s.offset ?? 0, timeout: 0, allowed_updates: ['message'] });
const updates = res.result || [];
if (!updates.length) return [];
const firstRun = s.offset === undefined;
s.offset = updates[updates.length - 1].update_id + 1;
// Confirm these updates to Telegram immediately: an overlapping run (slow searches can outlast the
// 15-second schedule) would otherwise fetch and answer the same messages again.
await tg('getUpdates', { offset: s.offset, timeout: 0, limit: 1 });
if (firstRun) return [{ json: { note: `skipped ${updates.length} old message(s) on first run` } }];   // never act on stale commands

const log = [];
for (const u of updates) {
  const m = u.message;
  if (!m || String(m.chat?.id) !== CHAT || typeof m.text !== 'string') continue;   // only your chat
  const text = m.text.trim();
  const cmd = text.split(/\s+/)[0].toLowerCase().replace(/@\w+$/, '');
  const rest = text.slice(text.split(/\s+/)[0].length).trim();
  const arg = rest.toLowerCase();
  const now = Date.now();

  if (cmd === '/movie' || cmd === '/show') {
    if (rest) await say('🔎 Searching…');
    try { await search(cmd === '/movie' ? 'movie' : 'tv', rest); } catch (e) { await say(`Seerr search failed: ${e.message}`); }
    log.push(`search ${cmd} ${rest}`); continue;
  }
  if (cmd === '/music' || cmd === '/ebook' || cmd === '/audiobook') {
    const kind = cmd.slice(1);
    if (rest) await say(`🔎 Searching ${ARR[kind].app}…`);
    try { await searchArr(kind, rest); } catch (e) { await say(`${ARR[kind].app} search failed: ${e.message}` + (/timeout|503/.test(e.message) ? `\nIts online book/music database seems slow or down right now. Try again in a few minutes.` : '')); }
    log.push(`search ${cmd} ${rest}`); continue;
  }
  if (cmd === '/pick') { try { await pick(arg); } catch (e) { await say(`Request failed: ${e.message}`); } log.push(`pick ${arg}`); continue; }
  if (cmd === '/requests') { try { await recentRequests(); } catch (e) { await say(`Couldn't load requests: ${e.message}`); } log.push('requests'); continue; }
  if (cmd === '/downloads') { try { await downloads(); } catch (e) { await say(`Couldn't reach qBittorrent: ${e.message}`); } log.push('downloads'); continue; }

  if (cmd === '/shutdown' || cmd === '/reboot') {
    const code = String(Math.floor(1000 + Math.random() * 9000));
    s.pending = { action: cmd.slice(1), code, expires: now + CONFIRM_SECONDS * 1000 };
    await say(`⚠️ ${cmd === '/shutdown' ? 'Shut down' : 'Reboot'} the server?\nEverything stops, including Home Assistant and all services` +
      (cmd === '/shutdown' ? `, and it won't come back until you press the power button.` : '. It should be back in about 5 minutes.') +
      `\n\nReply /confirm ${code} within ${CONFIRM_SECONDS / 60} minutes, or /cancel.`);
    log.push(`asked to confirm ${cmd}`);
  } else if (cmd === '/confirm') {
    const p = s.pending;
    if (!p || now > p.expires) { await say('Nothing to confirm (or it expired). Send /shutdown or /reboot again.'); s.pending = null; continue; }
    if (arg !== p.code) { await say('❌ Wrong code. Nothing happened.'); continue; }
    s.pending = null;
    await say(p.action === 'shutdown' ? '🛑 Shutting down gracefully now. Goodbye!' : '🔄 Rebooting gracefully now. Back in a few minutes.');
    await pve('POST', '/status', `command=${p.action}`);
    log.push(`${p.action} sent to Proxmox`);
  } else if (cmd === '/cancel') {
    s.pending = null; await say('👍 Cancelled. Nothing will happen.'); log.push('cancelled');
  } else if (cmd === '/status') {
    let text = '🖥️ Server status';
    try {
      const st = (await pve('GET', '/status')).data;
      text += `\nUp ${Math.floor(st.uptime / 86400)} d ${Math.floor(st.uptime % 86400 / 3600)} h · CPU ${Math.round(st.cpu * 100)}% · RAM ${Math.round(st.memory.used / st.memory.total * 100)}%`;
    } catch (e) { text += '\n(Proxmox unavailable)'; }
    try {
      const d = await helpers.httpRequest({ url: 'http://192.168.3.201:9878/json', json: true, timeout: 10000 });
      text += `\n${d.grid_present >= 1 ? '⚡ Grid ON' : '⚠️ Grid OFF'} · 🔋 ${Math.round(d.bat_soc)}% · ☀️ ${Math.round(d.pv_power)} W · 🏠 ${Math.round(d.load_power)} W`;
    } catch (e) { /* inverter info optional */ }
    await say(text); log.push('status');
  } else if (cmd === '/help' || cmd === '/start') {
    await say('🎬 Media\n/movie <title>: search movies\n/show <title>: search TV shows\n/music <artist>: search music (adds latest album)\n/ebook <title>: search ebooks\n/audiobook <title>: search audiobooks\n/pick <number>: request a search result\n/requests: recent requests\n/downloads: what is downloading\n\n🖥️ Server\n/status: server and power summary\n/shutdown: graceful shutdown (asks to confirm)\n/reboot: graceful reboot (asks to confirm)\n/cancel: cancel a pending shutdown/reboot');
  }
}
return log.length ? [{ json: { handled: log } }] : [];
